<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Support\Carbon;
use Illuminate\Support\Facades\Cache;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string|null $parent_id
 * @property string $slug
 * @property string $name
 * @property string|null $description
 * @property string|null $image_media_id
 * @property bool $sized
 * @property array|null $attributes
 * @property array|null $size_chart
 * @property array|null $sizes
 * @property int $position
 * @property bool $is_active
 * @property int $listings_count
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class Category extends Model
{
    use HasFactory, HasPrefixedId;

    protected static string $idPrefix = 'cat';

    protected $fillable = [
        'parent_id', 'slug', 'name', 'description', 'image_media_id', 'sized', 'attributes', 'size_chart', 'sizes',
        'position', 'is_active', 'listings_count',
    ];

    protected function casts(): array
    {
        return [
            'sized' => 'boolean',
            'is_active' => 'boolean',
            'attributes' => 'array',
            'size_chart' => 'array',
            'sizes' => 'array',
        ];
    }

    protected static function booted(): void
    {
        static::saved(fn () => Cache::forget('catalogue:tree'));
        static::deleted(fn () => Cache::forget('catalogue:tree'));
    }

    /** @return BelongsTo<Category, $this> */
    public function parent(): BelongsTo
    {
        return $this->belongsTo(self::class, 'parent_id');
    }

    /** @return HasMany<Category, $this> */
    public function children(): HasMany
    {
        return $this->hasMany(self::class, 'parent_id')->orderBy('position');
    }

    /** @return BelongsTo<Media, $this> */
    public function image(): BelongsTo
    {
        return $this->belongsTo(Media::class, 'image_media_id');
    }

    /** This category id plus all descendant ids (two levels deep is all the catalogue uses). */
    public function selfAndDescendantIds(): array
    {
        $childIds = self::query()->where('parent_id', $this->id)->pluck('id')->all();
        $grandIds = $childIds ? self::query()->whereIn('parent_id', $childIds)->pluck('id')->all() : [];

        return array_values(array_unique([$this->id, ...$childIds, ...$grandIds]));
    }

    /** Ancestors from root to this category (for breadcrumbs). */
    public function lineage(): array
    {
        $chain = [$this];
        $node = $this;
        while ($node->parent_id && count($chain) < 5) {
            $node = $node->parent;
            if (! $node) {
                break;
            }
            array_unshift($chain, $node);
        }

        return $chain;
    }
}
